    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Each 6-component is an occlusion. Find the occurrence of its surrounding
    # pattern elsewhere in the image, allowing reflections and rotations.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 6 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            mh, mw = r1 - r0 + 1, c1 - c0 + 1
            mask = set(cells)

            # Candidate source rectangle transformations: identity, flips,
            # and quarter-turn rotations.
            transforms = [
                lambda y, x: (y, x),
                lambda y, x: (y, mw - 1 - x),
                lambda y, x: (mh - 1 - y, x),
                lambda y, x: (mh - 1 - y, mw - 1 - x),
            ]
            if mh == mw:
                transforms += [
                    lambda y, x: (x, mh - 1 - y),
                    lambda y, x: (mw - 1 - x, y),
                    lambda y, x: (x, y),
                    lambda y, x: (mh - 1 - x, mw - 1 - y),
                ]

            best = None
            best_score = -1
            for ti, trans in enumerate(transforms):
                sh, sw = (mw, mh) if ti >= 4 else (mh, mw)
                for sr in range(h - sh + 1):
                    for sc in range(w - sw + 1):
                        if any(grid[sr + y][sc + x] == 6
                               for y in range(sh) for x in range(sw)):
                            continue
                        matches = total = 0
                        for dy in range(-3, mh + 3):
                            for dx in range(-3, mw + 3):
                                ty, tx = r0 + dy, c0 + dx
                                if not (0 <= ty < h and 0 <= tx < w):
                                    continue
                                if (ty, tx) in mask or grid[ty][tx] == 6:
                                    continue
                                if 0 <= dy < mh and 0 <= dx < mw:
                                    continue
                                yy, xx = trans(max(0, min(mh - 1, dy)),
                                               max(0, min(mw - 1, dx)))
                                sy, sx = sr + yy, sc + xx
                                if 0 <= sy < h and 0 <= sx < w and grid[sy][sx] != 6:
                                    total += 1
                                    matches += grid[ty][tx] == grid[sy][sx]
                        if total and matches / total > best_score:
                            best_score = matches / total
                            best = (sr, sc, trans)

            if best:
                sr, sc, trans = best
                for y, x in cells:
                    dy, dx = y - r0, x - c0
                    yy, xx = trans(dy, dx)
                    out[y][x] = grid[sr + yy][sc + xx]
