def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Eight orientations for comparing local neighborhoods.
    def orient(dy, dx, mode):
        if mode == 0: return dy, dx
        if mode == 1: return dy, -dx
        if mode == 2: return -dy, dx
        if mode == 3: return -dy, -dx
        if mode == 4: return dx, dy
        if mode == 5: return dx, -dy
        if mode == 6: return -dx, dy
        return -dx, -dy

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue

            candidates = []
            for rr in range(h):
                for cc in range(w):
                    if grid[rr][cc] == 6:
                        continue
                    for mode in range(8):
                        match = mismatch = count = 0
                        for dy in range(-5, 6):
                            for dx in range(-5, 6):
                                if dy == 0 and dx == 0:
                                    continue
                                y, x = r + dy, c + dx
                                ddy, ddx = orient(dy, dx, mode)
                                yy, xx = rr + ddy, cc + ddx
                                if not (0 <= y < h and 0 <= x < w and
                                        0 <= yy < h and 0 <= xx < w):
                                    continue
                                a, b = grid[y][x], grid[yy][xx]
                                if a == 6 or b == 6:
                                    continue
                                weight = 6 - max(abs(dy), abs(dx))
                                count += weight
                                if a == b:
                                    match += weight
                                else:
                                    mismatch += weight
                        if count >= 8:
                            candidates.append((match - mismatch, count,
                                               rr, cc, mode, grid[rr][cc]))

            if candidates:
                candidates.sort(reverse=True)
                # Pool the strongest neighborhood matches and choose the
                # most frequent center color among them.
                top_score = candidates[0][0]
                pool = [v for s, n, rr, cc, m, v in candidates
                        if s >= top_score - 2 and n >= candidates[0][1] // 2]
                if pool:
                    out[r][c] = max(set(pool), key=pool.count)

    return out
